using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using Object=UnityEngine.Object;
public static class RestoreTreeDetail {
 const string A="Assets/NewMap/FiveHangars/TreeDetailTemplates";
 struct Tree {public Vector3 p;public float scale,yaw;public int type;public bool distant;}
 static Vector3[] backdropVertices;static int[] backdropTriangles;static GameObject[] sources;static Dictionary<string,Mesh> templates=new Dictionary<string,Mesh>();static Dictionary<string,Material[]> templateMats=new Dictionary<string,Material[]>();
 static Material Map(Material m){var mapped=AssetDatabase.LoadAssetAtPath<Material>("Assets/NewMap/Materials/"+m.name+" - NewMap quality.mat");return mapped?mapped:m;}
 static bool BackdropHeight(Vector3 p,out float height){height=0;for(int k=0;k<backdropTriangles.Length;k+=3){var a=backdropVertices[backdropTriangles[k]];var b=backdropVertices[backdropTriangles[k+1]];var c=backdropVertices[backdropTriangles[k+2]];float d=(b.z-c.z)*(a.x-c.x)+(c.x-b.x)*(a.z-c.z);if(Mathf.Abs(d)<.00001f)continue;float u=((b.z-c.z)*(p.x-c.x)+(c.x-b.x)*(p.z-c.z))/d,v=((c.z-a.z)*(p.x-c.x)+(a.x-c.x)*(p.z-c.z))/d,w=1-u-v;if(u<-.0001f||v<-.0001f||w<-.0001f)continue;height=u*a.y+v*b.y+w*c.y;return true;}return false;}
 static Mesh Build(GameObject[] models,Tree[] trees,Vector3 center,int level,out Material[] materials){var groups=new Dictionary<Material,List<CombineInstance>>();foreach(var t in trees){var model=models[t.type];var ls=model.GetComponentInChildren<LODGroup>().GetLODs();foreach(var r in ls[level].renderers.OfType<MeshRenderer>()){var mesh=r.GetComponent<MeshFilter>().sharedMesh;for(int s=0;s<mesh.subMeshCount;s++){var mat=Map(r.sharedMaterials[s]);if(!groups.ContainsKey(mat))groups.Add(mat,new List<CombineInstance>());groups[mat].Add(new CombineInstance{mesh=mesh,subMeshIndex=s,transform=Matrix4x4.Translate(-center)*Matrix4x4.TRS(t.p,Quaternion.Euler(0,t.yaw,0),Vector3.one*t.scale)*model.transform.worldToLocalMatrix*r.transform.localToWorldMatrix});}}}var parts=new List<Mesh>();foreach(var group in groups){var m=new Mesh{indexFormat=IndexFormat.UInt32};m.CombineMeshes(group.Value.ToArray(),true,true);parts.Add(m);}var result=new Mesh{indexFormat=IndexFormat.UInt32};result.CombineMeshes(parts.Select(m=>new CombineInstance{mesh=m,transform=Matrix4x4.identity}).ToArray(),false,false);result.RecalculateBounds();foreach(var m in parts)Object.DestroyImmediate(m);materials=groups.Keys.ToArray();return result;}
 static Mesh Template(GameObject source,int level,out Material[] mats){string key=source.name+" LOD"+level;if(!templates.TryGetValue(key,out var mesh)){mesh=Build(new[]{source},new[]{new Tree{p=Vector3.zero,scale=1,type=0}},Vector3.zero,level,out mats);mesh.name=key;AssetDatabase.CreateAsset(mesh,A+"/"+key+".asset");templates.Add(key,mesh);templateMats.Add(key,mats);}else mats=templateMats[key];return mesh;}
 static string ModelName(string name)=>name.Split(new[]{" -"," ("},StringSplitOptions.None)[0];
 static MeshRenderer Renderer(Transform parent,string name,Mesh mesh,Material[] mats){var g=new GameObject(name);g.transform.SetParent(parent,false);g.layer=parent.gameObject.layer;g.AddComponent<MeshFilter>().sharedMesh=mesh;var r=g.AddComponent<MeshRenderer>();r.sharedMaterials=mats;r.shadowCastingMode=ShadowCastingMode.On;return r;}
 public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");if(Directory.Exists(A))throw new Exception("Detail restoration already applied");var root=GameObject.Find("New_Map").transform;var hills=root.Find("12_Farmyards_and_boundaries/Low poly hill groves");var terrain=root.GetComponentInChildren<Terrain>();var individual=root.GetComponentsInChildren<LODGroup>().Where(l=>l.name.Contains("Tree")).ToArray();var paths=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Imported/Toon Series/Toon Farm Pack/Prefabs"}).Select(AssetDatabase.GUIDToAssetPath).GroupBy(Path.GetFileNameWithoutExtension).ToDictionary(g=>g.Key,g=>g.First());var modelLookup=individual.Select(l=>ModelName(l.name)).Distinct().ToDictionary(n=>n,n=>AssetDatabase.LoadAssetAtPath<GameObject>(paths[n]));var sourceNames=root.Find("05_Landscape").GetComponentsInChildren<LODGroup>().Where(l=>l.name.StartsWith("TFP_Beech_Tree_")).GroupBy(l=>l.name).Select(g=>ModelName(g.First().name)).Take(3).ToArray();sources=sourceNames.Select(n=>modelLookup[n]).ToArray();
 var backdrop=root.Find("12_Farmyards_and_boundaries/Distant rolling hills - backdrop");var bm=backdrop.GetComponent<MeshFilter>().sharedMesh;backdropVertices=bm.vertices.Select(v=>backdrop.TransformPoint(v)).ToArray();backdropTriangles=bm.triangles;var rng=new System.Random(2601026);Func<float,float,float> random=(a,b)=>Mathf.Lerp(a,b,(float)rng.NextDouble());var trees=new List<Tree>();
 for(float z=-66;z<310;z+=8.5f)for(float x=-188;x<188;x+=8.5f){var p=new Vector3(x+random(-3,3),0,z+random(-3,3));float edge=Mathf.Min(Mathf.Min(p.x+192,192-p.x),Mathf.Min(p.z+70,314-p.z));if(edge<3||edge>26)continue;float density=Mathf.PerlinNoise(p.x*.026f+70,p.z*.026f+29);if(rng.NextDouble()>.36f+density*.52f)continue;p.y=terrain.SampleHeight(p)+terrain.transform.position.y-.12f;trees.Add(new Tree{p=p,scale=random(.7f,1.25f),yaw=random(0,360),type=rng.Next(sources.Length)});}
 for(float z=-178;z<422;z+=13)for(float x=-300;x<300;x+=13){var p=new Vector3(x+random(-4.5f,4.5f),0,z+random(-4.5f,4.5f));if(p.x>-191&&p.x<191&&p.z>-69&&p.z<313)continue;float height;if(!BackdropHeight(p,out height))continue;if(rng.NextDouble()>.3f+Mathf.PerlinNoise(p.x*.019f+14,p.z*.019f+61)*.48f)continue;p.y=height-.12f;trees.Add(new Tree{p=p,scale=random(.85f,1.5f),yaw=random(0,360),type=rng.Next(sources.Length),distant=true});}
 var cells=trees.GroupBy(t=>(t.distant?"Outer ":"Slope ")+Mathf.FloorToInt(t.p.x/42)+"_"+Mathf.FloorToInt(t.p.z/42)).ToArray();if(cells.Length!=hills.childCount)throw new Exception("Grove replay mismatch");foreach(var cell in cells)if(!hills.Find(cell.Key))throw new Exception("Missing grove "+cell.Key);
 Directory.CreateDirectory(A);AssetDatabase.Refresh();EditorSceneManager.SaveScene(root.gameObject.scene,"Temp/TreeOptimization/Gameplay.before-moderate-tree-detail.unity",true);int serial=0;long hillTop=0,hillFar=0,individualTop=0,individualFar=0;
 AssetDatabase.StartAssetEditing();try{
 foreach(var cell in cells){var owner=hills.Find(cell.Key);var lod=owner.GetComponent<LODGroup>();var oldChildren=owner.Cast<Transform>().ToArray();var ts=cell.ToArray();var center=new Vector3(ts.Average(t=>t.p.x),ts.Average(t=>t.p.y),ts.Average(t=>t.p.z));var levels=new LOD[3];for(int i=0;i<3;i++){Material[] mats;var replacement=Build(sources,ts,center,i+2,out mats);var path="Assets/NewMap/FiveHangars/HillTrees/Hill grove "+(++serial)+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(!existing)throw new Exception("Missing existing grove asset "+path);EditorUtility.CopySerialized(replacement,existing);existing.name=Path.GetFileNameWithoutExtension(path);EditorUtility.SetDirty(existing);var r=Renderer(owner,"Full 3D grove LOD "+i,existing,mats);levels[i]=new LOD(i==0?.5f:i==1?.12f:.004f,new UnityEngine.Renderer[]{r});if(i==0)hillTop+=existing.triangles.Length/3;if(i==2)hillFar+=existing.triangles.Length/3;Object.DestroyImmediate(replacement);}lod.SetLODs(levels);foreach(var t in oldChildren)Object.DestroyImmediate(t.gameObject);lod.RecalculateBounds();}
 foreach(var lod in individual){var model=modelLookup[ModelName(lod.name)];var old=lod.GetLODs().SelectMany(l=>l.renderers).Distinct().ToArray();var levels=new LOD[4];for(int i=0;i<4;i++){Material[] mats;var mesh=Template(model,i+1,out mats);var r=Renderer(lod.transform,"Complete 3D tree LOD "+i,mesh,mats);levels[i]=new LOD(i==0?.5f:i==1?.2f:i==2?.06f:.003f,new UnityEngine.Renderer[]{r});if(i==0)individualTop+=mesh.triangles.Length/3;if(i==3)individualFar+=mesh.triangles.Length/3;}float size=lod.size;var reference=lod.localReferencePoint;lod.SetLODs(levels);foreach(var r in old)Object.DestroyImmediate(r.gameObject);lod.size=size;lod.localReferencePoint=reference;}
 }finally{AssetDatabase.StopAssetEditing();}AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.gameObject.scene);string report="Moderate tree optimization, replacing the overly aggressive pass.\n340 ordinary trees: full 3D native LOD1 close, then LOD2/LOD3/LOD4; screen thresholds 0.5 / 0.2 / 0.06 / 0.003.\n227 hill cells: complete native 3D LOD2 / LOD3 / LOD4 at thresholds 0.5 / 0.12 / 0.004. No tree billboards remain in the active map.\nHill highest-detail triangles="+hillTop+"; far 3D representation="+hillFar+".\nOrdinary highest-detail triangles="+individualTop+"; far 3D representation="+individualFar+".\nCompared with original 4,870,800 top-detail tree triangles: "+(100*(1-(hillTop+individualTop)/4870800f)).ToString("F1")+"% lower top-detail budget.\nTree positions and colliders preserved; closed-hangar grain stays disabled. Source prefabs and global quality settings unchanged.";File.WriteAllText("output/TreeOptimization/moderate-detail.txt",report);return report;
 }
}
